using System.Text.Json.Serialization;

namespace VanPattenAIRouter.Models;

/// <summary>
///     Represents a single choice in a chat completion response.
/// </summary>
public class ChatChoice
{
    /// <summary>
    ///     The index of the choice in the list of choices.
    /// </summary>
    public int Index { get; set; }

    /// <summary>
    ///     The message generated by the model (non-streaming).
    /// </summary>
    public ChatMessage Message { get; set; } = new();

    /// <summary>
    ///     The message delta (streaming).
    /// </summary>
    [JsonPropertyName("delta")]
    public ChatMessageDelta? Delta { get; set; }

    /// <summary>
    ///     The reason the model stopped generating tokens. Can be "stop", "length", "tool_calls", "content_filter", or
    ///     "function_call".
    /// </summary>
    public string FinishReason { get; set; } = "stop";

    /// <summary>
    ///     Log probability information for the choice.
    /// </summary>
    [JsonPropertyName("logprobs")]
    public ChatLogprobs? Logprobs { get; set; }
}